int rrdset2anything_api_v1( /* <=== rrdset2anything_api_v1 */ 
          RRDSET *st
        , BUFFER *wb
        , BUFFER *dimensions
        , uint32_t format
        , long points
        , long long after
        , long long before
        , int group_method
